const host = '少年梦'
const branch = 'temp'
const version = '1.0.0'
const api = 'https://snd.vv9v.cn'
const apiAdmin = 'https://zqmy.vv9v.cn'

function releasePage() {
  this.java.startBrowser(`${apiAdmin}/source/release/?host=${host}&branch=${branch}&version=${version}&lastUpdateTime=${this.source.lastUpdateTime}`, '发布页')
}

function checkUpdate() {
  let lastCheckUpdateTime = Number(this.source.get('lastCheckUpdateTime')) || 0
  let now = Date.now()
  if (now - lastCheckUpdateTime < 12 * 3600 * 1000) return
  this.source.put('lastCheckUpdateTime', String(now))
  let data = requestApiUrl.call(this, '/source/sources', { host, branch, version }, apiAdmin)
  if (!data) return
  if (data.history[0].version != version) {
    releasePage.call(this)
  }
}

function getApiUrl(path, data, host = api) {
  const { source } = this
  data = Object.entries(data).map(v => v.join('=')).join('&')
  const option = {
    method: "GET",
    headers: {
      'authorization': `Bearer ${source.getVariable()}`
    }
  }
  const url = host + path + '?' + data + ',' + JSON.stringify(option)
  return url
}

function requestApiUrl(path, data, host = api) {
  const url = getApiUrl.call(this, path, data, host)
  try {
    let res = this.java.ajax(url)
    res = JSON.parse(res)
    if (res.code != 0) {
      this.java.longToast(`\n❌操作失败，code${res.code}：\n${res.msg}`)
    } else {
      return res.data
    }
  } catch (e) {
    this.java.log(`请求共享接口${path}异常：` + e.message)
  }
  return null
}

function getCNTimeString(time, format = 'YYYY/MM/DD HH:mm:ss') {
  const date = time ? new Date(time) : new Date()
  const year = date.getFullYear()
  const month = String(date.getMonth() + 1).padStart(2, '0')
  const day = String(date.getDate()).padStart(2, '0')
  const hours = String(date.getHours()).padStart(2, '0')
  const minutes = String(date.getMinutes()).padStart(2, '0')
  const seconds = String(date.getSeconds()).padStart(2, '0')
  return format.replace('YYYY', String(year))
    .replace('MM', month)
    .replace('DD', day)
    .replace('HH', hours)
    .replace('mm', minutes)
    .replace('ss', seconds)
}

