  let data = requestApiUrl('/system/dbinfo', {})
  if (!data) return
  let { msg } = data
  java.longToast(`\n✅${msg}`)
}

function downloadNovel() {
  let novelId = +String(result['书籍ID'])
  if (!novelId) {
    return java.longToast('\n❌请输入有效书籍ID')
  }
  let data = requestApiUrl('/novel/download', { novelId })
  if (!data) return
  let { msg } = data
  java.longToast(`\n✅${msg}`)
}

function buy(all) {
