@js:
let novelId = java.hexDecodeToString(result)
let vols = requestApiUrl('/novel/catalog', { novelId })

let cache = requestApiUrl('/novel/cache', { novelId }) || []
cache = cache.reduce((acc, d) => {
  acc[d.chapId] = d
  return acc
}, {})

let loginInfo = JSON.parse(source.getLoginInfo() || '{}')
loginInfo.书籍ID = novelId
source.putLoginInfo(JSON.stringify(loginInfo))

let chaps = []

for (let v of vols) {
  chaps.push({
    title: v.title,
    voltype: true
  })
  for (let c of v.chapterList) {
    let cacheChap = cache[c.id]
    let isShare = !!cacheChap
    let isBuy = c.lock == 1
    let isVip = !!c.isFree
    let tag = isBuy ? '🔑' : isShare ? cacheChap.s ? '🍎' : '🎉' : ''
    if (tag) tag += '  '
    let onlineTime = (cacheChap ? cacheChap.onlineTime : getCNTimeString(c.release_time_now * 1000)) || getCNTimeString(c.release_time_now * 1000) || ''
    let info = `${onlineTime} ┃ 字数：${c.FontCount || 0}`
    chaps.push({
      title: (isVip ? tag : '') + c.title,
      info: info + (isShare ? (cacheChap.s ? '🍎' : '🎉') : tag),
      isVip,
      isBuy: isBuy || (cacheChap && cacheChap.s),
      url: `data:;base64,${java.base64Encode(c.id)},{"type":"SNDapi","novelId":"${novelId}"}`
    })
  }
}

chaps

